def square(n):
    return n ** 2

def apply_all(func, items):
    result = []
    for i in items:
        result.append(func(i))
    return result

print(apply_all(square, [1, 2, 3]))
print(apply_all(len, ['ab', 'cde']))

def passed(g): return g >= 50
def honor(g): return g >= 85

def count_if(rule, grades):
    n = 0
    for g in grades:
        if rule(g):
            n += 1
    return n

grades = [45, 72, 90, 88, 30]
print(count_if(passed, grades), count_if(honor, grades))
